import { useState } from 'react'
import { Slider } from 'moru-ui'

export function VolumeControl() {
  const [volume, setVolume] = useState(50)
  return (
    <Slider
      label="Volume"
      name="volume"
      min={0}
      max={100}
      step={5}
      value={volume}
      onValueChange={setVolume}
      showValue
    />
  )
}
